PRAGMA foreign_keys=ON;
CREATE TABLE spots(id TEXT PRIMARY KEY,name TEXT NOT NULL,lat REAL NOT NULL,lon REAL NOT NULL,public INTEGER NOT NULL DEFAULT 0 CHECK(public IN(0,1)),data TEXT NOT NULL,deleted_at TEXT);
CREATE TABLE spot_geometries(id TEXT PRIMARY KEY,spot_id TEXT REFERENCES spots(id),kind TEXT NOT NULL,geojson TEXT NOT NULL,original_id TEXT);
CREATE TABLE spot_exposure_sectors(spot_id TEXT REFERENCES spots(id),bearing INTEGER,fetch_m REAL,classification TEXT,source TEXT,PRIMARY KEY(spot_id,bearing));
CREATE TABLE spot_local_parameters(spot_id TEXT PRIMARY KEY REFERENCES spots(id),parameters TEXT NOT NULL,validation_id TEXT);
CREATE TABLE providers(id TEXT PRIMARY KEY,configuration TEXT NOT NULL,status TEXT,last_checked TEXT);
CREATE TABLE forecast_runs(id TEXT PRIMARY KEY,spot_id TEXT REFERENCES spots(id),downloaded_at TEXT NOT NULL,expires_at TEXT NOT NULL,payload TEXT NOT NULL);
CREATE INDEX forecast_by_spot ON forecast_runs(spot_id,downloaded_at DESC);
CREATE TABLE forecast_values(run_id TEXT REFERENCES forecast_runs(id) ON DELETE CASCADE,valid_at TEXT,variable TEXT,value REAL,unit TEXT,source TEXT,PRIMARY KEY(run_id,valid_at,variable,source));
CREATE TABLE local_estimates(run_id TEXT REFERENCES forecast_runs(id) ON DELETE CASCADE,valid_at TEXT,method TEXT,estimate TEXT,PRIMARY KEY(run_id,valid_at));
CREATE TABLE forecast_quality(run_id TEXT PRIMARY KEY REFERENCES forecast_runs(id) ON DELETE CASCADE,quality TEXT NOT NULL);
CREATE TABLE distribution_lists(id TEXT PRIMARY KEY,name TEXT NOT NULL);
CREATE TABLE subscribers(id TEXT PRIMARY KEY,list_id TEXT REFERENCES distribution_lists(id),email TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active' CHECK(status IN('active','unsubscribed')),unsubscribe_token TEXT UNIQUE NOT NULL,consent_at TEXT NOT NULL,UNIQUE(list_id,email));
CREATE TABLE alert_rules(id TEXT PRIMARY KEY,spot_id TEXT REFERENCES spots(id),list_id TEXT REFERENCES distribution_lists(id),enabled INTEGER NOT NULL DEFAULT 1,configuration TEXT NOT NULL,last_sent_at TEXT,last_fingerprint TEXT);
CREATE TABLE alert_evaluations(id TEXT PRIMARY KEY,rule_id TEXT REFERENCES alert_rules(id),evaluated_at TEXT NOT NULL,result TEXT NOT NULL);
CREATE INDEX evaluation_by_rule ON alert_evaluations(rule_id,evaluated_at DESC);
CREATE TABLE alert_deliveries(id TEXT PRIMARY KEY,rule_id TEXT REFERENCES alert_rules(id),subscriber_id TEXT REFERENCES subscribers(id),fingerprint TEXT NOT NULL,payload TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,provider_id TEXT,error TEXT,next_attempt TEXT,created_at TEXT NOT NULL,UNIQUE(rule_id,subscriber_id,fingerprint));
CREATE INDEX delivery_queue ON alert_deliveries(status,next_attempt);
CREATE TABLE admin_users(id TEXT PRIMARY KEY,role TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE audit_log(id TEXT PRIMARY KEY,created_at TEXT NOT NULL,action TEXT NOT NULL,entity_id TEXT);
CREATE TABLE job_locks(id TEXT PRIMARY KEY,expires_at TEXT NOT NULL);
CREATE TABLE rate_limits(key TEXT PRIMARY KEY,window INTEGER NOT NULL,count INTEGER NOT NULL);
